HOLIKA=lambda: demon('#5a2a6a')
COLS=['#e0306a','#ffd60a','#2a9d6f','#1d6fb8','#ff8c1a','#7a3fa0']
def splashes(w,h,n=14): return ''.join(g((53*k)%w,(37*k*k)%h,0.6+(k%3)*.3,splash(COLS[k%6])) for k in range(1,n))
COV=covart('A bonfire under a full moon on one side, and people throwing coloured powder on the other',f'<rect width="440" height="196" fill="#20243a"/><rect x="220" width="220" height="196" fill="#fff3cf"/>'+g(80,40,1,moonrise(0,0,20))+g(110,190,1.6,pyre())+g(110,175,1.4,fire())+''.join(g(220+x,196,1,person(c)) for x,c in [(60,'#1d6fb8'),(120,'#c0392b'),(175,'#2a9d6f')])+''.join(g(220+x,120,1,splash(c)) for x,c in [(40,'#e0306a'),(100,'#ffd60a'),(160,'#1d6fb8'),(200,'#2a9d6f')]))
pp=[foreword(i,['On the last full moon of the lunar year, in Phālguna, India first lights a fire and then throws colour. In the north the fire is <b>Holikā’s</b>, the aunt who tried to burn the boy Prahlāda; in Karnataka and Tamil Nadu it is <b>Kāma’s</b>, the god of love whom Śiva burned with his third eye. The next morning belongs to <b>Kṛṣṇa</b>, who coloured Rādhā’s face.','This article tells all three stories in full, gives the verses behind them, and goes region by region: Braj and Barsānā, Bengal’s swing festival, Bagalkoṭ’s Holi Habba and Karnataka’s Kāmaṇṇa, the coast and Goa, with the old history of a spring festival far older than any one of its stories.'],[('z','Why burn something before we play?'),('b','To start clean, Zappy. The fire takes the old year’s rubbish; then the colours look brighter.')]),
 glance([('Name','Holi, Holikā; Kāmana habba / Kāmana huṇṇime (Karnataka); Kāma dahana; Dol Jātrā (Bengal, Odisha); Śigmo (Goa)'),('When','Phālguna Pūrṇimā, the last full moon of the lunar year; late February or March'),('Night','A bonfire: Holikā burned (north) or Kāma burned (south)'),('Morning','Colour, water, songs, visits; in the north the next day, Raṅg Pañcamī five days later in places'),('Stories','Prahlāda and Holikā; Śiva and Kāma; Rādhā and Kṛṣṇa'),('Texts','Bhāgavata Purāṇa 7 (Prahlāda); Śiva Purāṇa, Rudra Saṃhitā (Kāma); Holikā in later Purāṇas and pūjā manuals'),('Spirit','“Bura na māno, Holī hai”: don’t take offence, it’s Holi')],svg(560,140,'A pyre and splashes of colour',ground(560,140,110)+g(140,110,1.3,pyre())+g(140,96,1.1,fire())+splashes(560,100)+g(420,40,1,moonrise(0,0,18)))),
 reading('moon','THE LAST FULL MOON','Phālguna Pūrṇimā and the turn of the year',svg(560,160,'Twelve full moons in a row with the last one, Phālguna, glowing',f'<rect width="560" height="160" fill="#20243a"/>'+''.join(f'<circle cx="{30+k*45}" cy="70" r="15" fill="{"#ffd60a" if k==11 else "#cfd8e6"}" stroke="#111" stroke-width="1.5"/>' for k in range(12))+lab(525,110,'Phālguna').replace('#111','#fff8d0')+lab(30,110,'Caitra').replace('#111','#fff8d0')),['<b>The end of the year.</b> In the lunar calendar used across Karnataka, Phālguna is the last month; the new year, '+L('/festivals/ugadi/','Ugādi')+', comes about two weeks after Holi. Holi is the year’s last full-moon feast, a burning of the old before the new begins.','<b>The turn of the season.</b> Winter is over, the rabi harvest is ripening in the north, the palāśa trees are in flame-coloured flower. Many scholars read the fire and the play as an old spring festival, older than any single story now told about it.','<b>The fire and the day after.</b> The bonfire is lit on the Pūrṇimā evening, in a window the almanac chooses so as to avoid <i>bhadrā</i>, a division of the day avoided for beginnings. The colours come the next morning; in parts of Maharashtra and central India they come again on <b>Raṅg Pañcamī</b>, five days later.','<b>Two days, one festival.</b> In Karnataka the evening is the main event (Kāmana huṇṇime, Kāma’s full moon), while the colour play is strongest in the north of the state.'],[('z','So Holi says goodbye to the year?'),('b','The last full moon, Zappy. Burn the old, laugh, and walk into Ugādi clean.')],'The year’s <b>last full moon</b>.'),
 reading('history','A VERY OLD SPRING FESTIVAL','What the old records say',svg(560,150,'A timeline of old texts with a flame at each mark',ground(560,150,100,'#e3eaf3')+'<path d="M30 80 h500" stroke-width="3"/>'+''.join(g(x,74,1,lamp())+lab(x,100,t)+lab(x,116,s) for x,t,s in [(70,'sūtra age','Gṛhya-sūtras'),(200,'5th c.','Kālidāsa'),(330,'7th c.','Ratnāvalī'),(460,'16th c.','Hampi reliefs')])),['<b>The sūtras.</b> The name appears as <i>Holākā</i> in early ritual literature: the Pūrva Mīmāṃsā sūtras of Jaimini discuss it as a rite kept in the east, and the Kāṭhaka Gṛhya-sūtra mentions a full-moon rite of the same name. What exactly was done then is not clear.','<b>The poets.</b> Kālidāsa’s works know a spring festival of love, and Harṣa’s seventh-century play <i>Ratnāvalī</i> opens with the <b>Madanotsava</b>, the festival of the love-god, where townspeople spray one another with coloured water and powder.','<b>Vijayanagara.</b> Reliefs at Hampi show people squirting coloured water from syringes, the ancestor of today’s <i>pichkārī</i>: Karnataka has carved Holi in stone.','<b>Many stories, one festival.</b> Over time three stories gathered around the same full moon: Prahlāda and Holikā, Śiva and Kāma, Rādhā and Kṛṣṇa. Different regions lead with different ones; all of them fit a festival of fire followed by play.'],[('z','The Madanotsava was a festival of the love-god?'),('b','Yes, Zappy. And in Karnataka the love-god is still at the centre of Holi. You’ll see why in a few pages.')],'Older than <b>any one story</b>.'),
 story('prahlada1','THE BOY WHO WOULD NOT STOP','Prahlāda and his father',strip('Three panels: the demon king on his throne; the boy Prahlāda praying to Viṣṇu at school; the king ordering soldiers against the boy',[panel([(HIRA(),1.1)],'#fde4e4',150),panel([(PRA(),1.2),(lotus(),1)],'#fff3cf',150),panel([(HIRA(),.9),(demon(),.8),(PRA(),.9)],'#e9e3f5',150)],['the king','the boy prays','the attacks begin']),'The story is told in the Bhāgavata Purāṇa, book 7, chapters 4–8.',['<b>Hiraṇyakaśipu</b>, king of the daityas, hated Viṣṇu, who had killed his brother Hiraṇyākṣa. By fierce penance he won a boon that seemed to make him unkillable, and ordered the three worlds to worship him alone.','His little son <b>Prahlāda</b> had heard of Viṣṇu while still in his mother’s womb, from the sage Nārada. At school, sent to learn statecraft, he taught his classmates devotion instead.','Asked by his father what was the best thing he had learned, the boy answered with the nine forms of devotion (next page). The king flew into a rage.','He had the boy attacked with weapons, trampled by elephants, bitten by serpents, poisoned, thrown from a height. Each time Prahlāda remembered Viṣṇu and came to no harm.','At last the king turned to his sister <b>Holikā</b>.'],[('z','Why didn’t the boy just pretend?'),('b','Because he couldn’t lie about what he loved, Zappy. That’s the whole point of Prahlāda.')],'Devotion that <b>will not bend</b>.'),
 verse('v-prahlada','Bhāgavata 7.5.23','The nine forms of devotion, Prahlāda’s answer',['śravaṇaṃ kīrtanaṃ viṣṇoḥ smaraṇaṃ pāda-sevanam','arcanaṃ vandanaṃ dāsyaṃ sakhyam ātma-nivedanam'],svg(200,150,'A small boy with folded hands, nine little lamps around him',ground(200,150,128,'#fff3cf')+g(100,140,1.2,PRA())+''.join(g(100+70*__import__("math").cos(k*0.7-2.9),75+45*__import__("math").sin(k*0.7-2.9),.7,lamp()) for k in range(9))),'Hearing about Viṣṇu, singing of him, remembering him, serving his feet, worship, salutation, service, friendship, and the offering of one’s whole self.',[('śravaṇam','hearing'),('kīrtanam','singing, praising'),('smaraṇam','remembering'),('pāda-sevanam','serving the feet'),('dāsyam','service'),('ātma-nivedanam','offering oneself')],'<b>A child’s syllabus.</b> This is what Prahlāda answers when his father asks for the best of his studies; the next verse adds that whoever practises these nine has learned the highest learning. Many teachers read the bonfire as the test of the ninth, <i>ātma-nivedanam</i>: a boy who has given himself wholly cannot be burned. (Interpretation.)',k='<b>Nine ways</b> to love God.',note='Text: Bhāgavata Purāṇa 7.5.23, BBT edition (prabhupadabooks.com), set in IAST.'),
 story('holika','HOLIKĀ AND THE FIRE','Why the bonfire burns',strip('Three panels: Holikā holding Prahlāda on a pyre; flames rising; Holikā burned and Prahlāda walking out',[panel([(pyre(),1),(HOLIKA(),.9),(PRA(),.7)],'#fde4e4',150),panel([(pyre(),1),(fire(),1.4)],'#2a2a3a',150),panel([(fire(),.8),(PRA(),1)],'#fff3cf',150)],['on the pyre','the fire','the boy walks out']),'The Bhāgavata itself tells of fire among the king’s attempts but does not name Holikā; her story is told in later Purāṇic retellings and in every north Indian home.',['<b>Holikā</b>, the king’s sister, could not be harmed by fire: by a boon, say some tellings, or by a fire-proof cloak, say others.','On the king’s order a great pyre was built. Holikā sat on it with the boy Prahlāda in her lap, and the pyre was lit.','Prahlāda only repeated the name of Viṣṇu. The flames rose.','Her protection failed her, used as it was to kill a child: in the cloak telling, the wind lifted the cloak off her and wrapped it round the boy. Holikā burned; Prahlāda walked out unharmed.','The bonfire on Holi night is <b>Holikā Dahana</b>, “the burning of Holikā”. Soon after, Viṣṇu came out of a pillar as Narasiṃha and ended Hiraṇyakaśipu (read our '+L('/vishnu/dashavatara/narasimha/','Narasiṃha article')+').'],[('z','Her boon stopped working?'),('b','A gift used for cruelty turns against its owner, Zappy. The tellings agree on that, whatever the details.')],'The fire <b>knows the difference</b>.'),
 verse('v-holika','The Holikā verse','Said at the bonfire in north Indian pūjā manuals',['asṛkpābhayasantrastaiḥ kṛtā tvaṃ holi bāliśaiḥ','atas tvāṃ pūjayiṣyāmi bhūte bhūtipradā bhava'],svg(200,150,'People circling a lit bonfire with offerings',ground(200,150,128)+g(100,130,1,pyre())+g(100,118,.9,fire())+'<ellipse cx="100" cy="128" rx="80" ry="16" fill="none" stroke="#c0392b" stroke-width="2" stroke-dasharray="5 4"/>'+g(30,140,.8,person('#1d6fb8'))+g(170,140,.8,person('#2a9d6f'))),'O Holī, you were made by foolish people terrified of blood-drinkers; therefore I worship you: O being, be a giver of prosperity.',[('asṛkpa','blood-drinkers, demons'),('bhaya-santrastaiḥ','by those struck with fear'),('bāliśaiḥ','by the foolish, the childish'),('pūjayiṣyāmi','I shall worship'),('bhūte','O being'),('bhūti-pradā','giver of prosperity')],'<b>A surprising prayer.</b> The verse treats the pyre itself as Holī, a being made out of fear, and asks her to turn into a giver of wealth. It hints at the oldest layer of the festival: a fire lit against the dark and the frightening, before any one story was attached. At the fire people circle three or seven times, throw in coconut, new grain and dung-cakes, and take a little ash home.',k='Fear <b>turned into blessing</b>.',note='Text as given in modern Holī pūjā manuals (e.g. dekhopanchang.com). We have not traced it to a single Purāṇa; readings vary.'),
 story('kama','ŚIVA BURNS KĀMA','The story Karnataka tells',strip('Three panels: Śiva in meditation with Pārvatī serving him; Kāma aiming a flower-arrow; Śiva’s third eye opening and Kāma burning',[panel([(SH(),1),(devi(items=('lotus',)),.8)],'#e3eaf3',150),panel([(KAMA(),1.1),(bowarrow_flower(),1)],'#fde4e4',150),panel([(SH(),.9),(fire(),.9)],'#2a2a3a',150)],['Śiva in tapas','the flower-arrow','the third eye']),'Told in the Śiva Purāṇa (Rudra Saṃhitā, Pārvatī Khaṇḍa) and in Kālidāsa’s Kumārasambhava.',['After Satī’s death Śiva sat in deep meditation on the mountain, turned away from the world. Pārvatī, Satī reborn, served him daily, but he did not open his eyes.','The demon <b>Tāraka</b> could be killed only by a son of Śiva. The gods sent <b>Kāma</b>, the god of love, with his sugarcane bow and flower-arrows, and spring itself to help him.','As Pārvatī came near, Kāma loosed his arrow. Śiva stirred, felt desire, and looked for its cause.','He saw Kāma hiding, and from his <b>third eye</b> a flame leapt out and burned the love-god to ash.','Kāma’s wife <b>Rati</b> wept and pleaded. Śiva relented: Kāma would live on, but without a body, as <b>Anaṅga</b>, and be restored to her in a later age (as Pradyumna, son of Kṛṣṇa). Pārvatī won Śiva by her own penance, and their son Skanda killed Tāraka.'],[('z','So love was burned?'),('b','Lust was, many teachers say: the desire that disturbs. Love comes back, without a body. A fine idea for a spring festival.')],'Desire burned; <b>love returns</b>.'),
 reading('kamanahabba','KĀMANA HABBA IN KARNATAKA','Rati, Kāmaṇṇa and the full moon of Kāma',svg(560,170,'A street with a seated effigy of Kāmaṇṇa beside Rati, children drumming, and a bonfire',ground(560,170,135)+g(150,150,1.2,KAMA())+g(200,150,1,RATI())+g(320,150,.9,child())+g(370,150,.9,child())+g(345,110,1,'<ellipse rx="16" ry="10" fill="#c98a5a"/>')+g(480,150,1.1,pyre())+g(480,138,1,fire())),['<b>The names.</b> In Karnataka Holi is <b>Kāmana habba</b>, the festival of Kāma, and the full moon is <b>Kāmana huṇṇime</b>. For days before, children go round collecting wood and dung-cakes for the fire, drumming on the <i>halage</i> and calling out songs, some of them cheeky.','<b>Kāmaṇṇa and Rati.</b> In towns and villages, especially in the north of the state, figures of <b>Kāmaṇṇa</b> (Kāma) and Rati are set up at street corners and worshipped. On the full-moon night Kāmaṇṇa is burned on the bonfire, re-enacting Śiva’s third eye; in some places women sing Rati’s lament.','<b>Bagalkoṭ’s Holi Habba.</b> Bagalkoṭ keeps the most famous Holi in the state: it opens with the Kāma dahana bonfire and then runs for several days of colour, drums and processions through the old town’s lanes.','<b>The coast and the hills.</b> On the coast communities keep the <b>Hōḷi kuṇita</b>, a dance tradition with days of preparation and visits from house to house. Around Mysuru the festival is quieter, often just the fire and a little colour for the children.'],[('z','Do we have Holi in Mysuru?'),('b','Quietly, Zappy. Go north to Dharwad, Bagalkoṭ or Vijayapura and you’ll come home a different colour.')],'In Karnataka, <b>Kāma burns</b>.'),
 story('radha','RĀDHĀ’S COLOURED FACE','Kṛṣṇa’s Holi',strip('Three panels: little dark Kṛṣṇa complaining to Yaśodā; Kṛṣṇa throwing colour at Rādhā; the gopīs and gopas playing with colours',[panel([(krishna_child(),1.1),(mother('#e0a800'),1)],'#fff3cf',150),panel([(god('#2a5aa8'),1),(splash('#e0306a'),1),(person('#e0306a'),1)],'#fde4e4',150),panel([(person('#7a3fa0'),.8),(splash('#ffd60a'),1),(person('#2a9d6f'),.8)],'#e3f5e9',150)],['why is she fair?','the first colour','all Vraja plays']),'In Braj, around Mathurā and Vṛndāvana, Holi belongs to Kṛṣṇa. This is the household telling, sung in countless Braj songs rather than told in one scripture.',['Little <b>Kṛṣṇa</b>, dark as a rain-cloud, came to his mother <b>Yaśodā</b> with a complaint: why was Rādhā so fair and he so dark?','Yaśodā laughed and said: then go and colour her face any colour you like.','So Kṛṣṇa went with his friends to Rādhā’s village and smeared colour on her face. Rādhā and her friends answered with colour and water of their own.','The whole of Vraja joined in: cowherds and milkmaids, with pichkārīs of coloured water and fistfuls of red powder (<i>gulāl</i>), with songs and drums.','Braj still plays it for a week or more. In <b>Barsānā</b>, Rādhā’s village, the women of the town playfully beat the men of Kṛṣṇa’s village <b>Nandgāon</b> with sticks (<b>Laṭhmār Holi</b>), and Vṛndāvana’s temples hold a Holi of flowers.'],[('z','Women beating men with sticks?'),('b','Playfully, Zappy, against padded shields. Kṛṣṇa’s friends teased Rādhā’s village; the village answers every year.')],'Colour as <b>love’s play</b>.'),
 cards('regions','HOLI ACROSS INDIA','Swings, songs and the month-long Śigmo',fig_row('A swing with an image, a drum, a dancer and splashes of colour',[(swing(),1),(splash('#e0306a'),1.4),(person('#7a3fa0'),1.2),(splash('#ffd60a'),1.4)],['Dol','gulāl','Śigmo','colour'],gy=150),[('🎪','Bengal and Odisha','<b>Dol Jātrā</b>: images of Rādhā and Kṛṣṇa (in Odisha, of Jagannātha’s representatives) are carried on decorated swings, with coloured powder. The full moon is also Gaura Pūrṇimā, the birthday of Caitanya.'),('🥁','Goa and the Konkan','<b>Śigmo</b> (Śimgā): a spring festival of about a month with folk dances, drums and processions of floats.'),('🌕','Manipur','Holi merges with <b>Yaoshang</b>, five days of sports, songs and the thabal chongba dance under the full moon.'),('🔥','Tamil Nadu and Andhra','<b>Kāman paṇḍigai</b> and the Kāmudu fire: Kāma dahana, Rati’s lament in song, and pantomimes of the love-god before his effigy is burned.')],[('z','So Bengal swings while Karnataka burns?'),('b','And Braj beats, Goa dances and Manipur plays football, Zappy. One full moon, many temperaments.')],'One moon, <b>many festivals</b>.'),
 reading('colours','THE COLOURS','Where they came from, and why',fig_row('Palāśa flowers, turmeric, kuṅkuma and leaves, each with its colour',[(lotus('#ff8c1a','#e0501a'),1.6),(splash('#ffd60a'),1.2),(splash('#c0392b'),1.2),(leaf(),1.6)],['palāśa','turmeric','kuṅkuma','leaves'],gy=150),['<b>From the forest.</b> The old colours came from plants: the flame-orange flowers of the <b>palāśa</b> (ṭesū) soaked overnight for orange water; turmeric for yellow; kuṅkuma and red sandal for red; henna and leaves for green; indigo for blue.','<b>Why colour at all.</b> The Kṛṣṇa story gives the reason most people know. Many also read the colour as the levelling of the festival: for one morning rich and poor, old and young, are the same colour. (Interpretation.)','<b>A season’s medicine.</b> Traditional writers point out that several of the plant colours, turmeric and neem among them, were valued as remedies at the turn of the season. Treat this as tradition rather than medicine.','<b>Today’s caution.</b> Some cheap commercial colours have been found to contain harmful dyes and metals. Many families now go back to natural colours, keep colour out of eyes and mouths, and ask before colouring anyone who has not come to play.'],[('z','Can I make colours at home?'),('b','Turmeric with a little flour for yellow, beetroot for pink, soaked palāśa flowers for orange. Grandmother’s chemistry set, Zappy.')],'Colours <b>from the garden</b>.'),
 reading('meaning','WHAT HOLI MEANS','Fire, then play',svg(560,160,'A bonfire on the left turning into a burst of colours on the right',f'<rect width="280" height="160" fill="#20243a"/><rect x="280" width="280" height="160" fill="#fff3cf"/>'+g(140,140,1.3,pyre())+g(140,124,1.2,fire())+''.join(g(320+k*45,60+(k%2)*50,1,splash(COLS[k])) for k in range(6))),['<b>The fire.</b> Each of the stories burns something: Holikā’s cruelty, Kāma’s disturbing desire, the old year’s rubbish. Many teachers read the bonfire as the burning of what we do not want to carry into the new year. (Interpretation.)','<b>The colour.</b> Then comes play without rank: colour the friend you quarrelled with, the elder, the neighbour. The north’s saying “<b>bura na māno, Holī hai</b>”, don’t take it badly, it’s Holi, is a licence to forgive.','<b>The devotee.</b> Prahlāda gives the festival its spine: devotion that fear cannot bend. Rādhā and Kṛṣṇa give it its joy. Śiva and Rati give it a lesson about desire.','<b>Kindness.</b> Holi’s licence is for play, not for forcing. Colour those who want it, spare the animals, keep water use sensible, and leave the old and the unwilling in peace.'],[('z','If I could do one thing for Holi?'),('b','Throw one thing you don’t need into the fire, Zappy, then put colour on the face of someone you’ve been cross with. Holi done.')],'Burn the old, <b>forgive, then play</b>.'),
 end(i,['<b>When.</b> Phālguna Pūrṇimā, the last full moon of the year.','<b>Fire.</b> Holikā burns, Prahlāda walks out; in Karnataka, Kāma burns.','<b>Prahlāda.</b> Nine forms of devotion; Narasiṃha soon after.','<b>Colour.</b> Kṛṣṇa colours Rādhā; Braj plays for a week.','<b>Karnataka.</b> Kāmana habba, Kāmaṇṇa and Rati, Bagalkoṭ’s Holi Habba.'],'Previous: '+L('/festivals/maha-shivaratri/','Mahāśivarātri')+'. Next: '+L('/festivals/ugadi/','Ugādi')+', the new year two weeks later.','Holi: fire, colour and the full moon'),
 sources([('Stories:','Bhāgavata Purāṇa 7.4–8 (Prahlāda, Narasiṃha; 7.5.23 text from the BBT edition); Śiva Purāṇa, Rudra Saṃhitā, Pārvatī Khaṇḍa and Kālidāsa’s Kumārasambhava (Kāma burned, Rati); Braj tradition (Rādhā and Kṛṣṇa).'),('History and customs:','Wikipedia, “Holi”, “Holika Dahan” (sūtra mentions, Ratnāvalī, Hampi reliefs, regional names); Karnataka Tourism and utsav.gov.in (Bagalkoṭ Holi Habba, Kāma dahana); Deccan Herald (Hōḷi kuṇita on the coast).'),('Verse:','Holikā verse as in modern pūjā manuals (dekhopanchang.com).')],'Holikā’s cloak and the source of her boon (tellings differ; she is not named in the Bhāgavata); the Rādhā-Yaśodā story (oral and song tradition); the source of the Holikā verse; medicinal claims for colours (tradition); details of village customs (vary).','Bhāgavata numbering as in the BBT edition.')]
build(i,'FIRE · COLOUR · PRAHLĀDA, KĀMA AND KṚṢṆA',COV,'Fire at night, colour in the morning','The <b>full moon</b> of Phālguna, the <b>three stories</b> told in full, the verses behind them, and how <b>Karnataka</b> keeps Kāmana habba, with Braj, Bengal, Goa and beyond.','Holi explained: Phālguna Pūrṇimā, Prahlāda and Holikā with Bhāgavata 7.5.23, Śiva burning Kāma and Karnataka’s Kāmana habba, Rādhā and Kṛṣṇa’s colours in Braj, Bagalkoṭ’s Holi Habba, Dol Jātrā, Śigmo, the history and natural colours.',pp)
print('holi ok',len(pp)+2)
